char* write_results(const char* results) {
    // BEGIN SOLUTION
    char template[] = "/tmp/tmpXXXXXX";
    char* filename = NULL;
    int fd;
    FILE* temp_file;

    // Create a unique temporary file
    fd = mkstemp(template);
    if (fd == -1) {
